/* Tony Khan Simulator — deeply silly gimmick prospects.
   Now and then the scouting board turns up one of these. Each has a bio, its own match moment (m) and its own promo
   opener and lines (p), which only come up when that wrestler is involved. Everything else (training, feuds, titles)
   works like any other prospect. Entries marked old:1 are retired: they no longer turn up for scouting or pitches, but
   wrestlers who already have them keep their moments. pal links two gimmicks that click as partners. Fields: k key · n name · g M/F · st style · al face/heel · tier · bio · ring/mic/pop
   stat nudges · m {t, ch} · p {t, ch}. */
'use strict';
const GIMMICKS=[
{k:'mime',n:'Silence the Mime',g:'M',st:'sh',al:'h',tier:'bluechip',mic:-15,pop:6,bio:"Has not spoken a word since 2011. Communicates exclusively through an invisible box.",
 m:{t:"{A} traps {B} in an invisible box. The referee is genuinely unsure whether this counts as a submission.",ch:[
  {t:"Pull an invisible rope and 'drag' {B} into the corner",s:'pop',d:.1,st:.5,popA:2,heat:6,ok:"{B} sells it. The crowd has no idea why they're cheering.",no:"{B} simply walks out of the invisible box. Devastating."},
  {al:'h',t:"Mime a steel chair — then hit {B} with a real one",s:'luck',d:.05,st:.5,heat:14,ok:"Nobody saw the real chair coming. The purest deception in wrestling history.",no:"The ref confiscates the real chair. The invisible one is allowed."}]},
 p:{t:"{A} walks to the ring, picks up the microphone, and stares at it. For a long time.",ch:[
  {key:1,t:"Perform an entire promo in total silence",s:'pop',d:.15,p:4,ok:`Four minutes of mime. The crowd somehow understood most of it. Standing ovation.`,g:`Four minutes of mime: the invisible box, the invisible ladder, the invisible belt lifted high. At the end, {A} mimes dropping a mic. The crowd somehow understood every word. Standing ovation.`,no:`The crowd chants "SAY SOMETHING." {A} refuses. Nobody wins.`,b:`{A} mimes the box, then forgets where the walls are and walks through one. The crowd chants "SAY SOMETHING."`},
  {t:"Mime crying about how misunderstood they are",s:'pop',d:.05,p:3,ok:`{A} mimes crying about how misunderstood they are. A single invisible tear. The front row is moved.`,g:`{A} kneels, mimes one tear, catches it, looks at it, and puts it in an invisible pocket. The front row is emotionally destroyed.`,no:`It looks like they have something in their eye.`,b:`{A} mimes crying so hard they mime blowing their nose, loudly, which isn't miming. It looks like they have something in their eye.`}]}},
{k:'actor',old:1,n:'Famous Actor Chad Brightwell',g:'M',st:'sh',al:'h',tier:'prospect',mic:8,bio:"Insists he's a household-name Hollywood star. Nobody has seen any of his movies. Neither has IMDb.",
 m:{t:"{A} stops mid-match to ask the director — there is no director — for another take.",ch:[
  {t:"Redo the last move, 'with more feeling'",s:'pop',d:.1,st:.5,popA:2,ok:"Take two is a masterpiece. The crowd demands an Oscar.",no:"Take two is somehow worse than take one."},
  {al:'h',t:"Demand {B} 'hit their mark' and then clothesline them on it",s:'ring',d:.05,st:.5,heat:12,ok:"{B} stands exactly where they were told and gets flattened. Hollywood is brutal.",no:"{B} ignores the blocking notes."}]},
 p:{t:"{A} walks out in sunglasses and a bathrobe, signing autographs nobody asked for.",ch:[
  {key:1,t:"Recite the plot of his 'upcoming blockbuster'",s:'mic',d:.1,p:3,ok:`"My next movie? A thriller. Explosions. Me. Summer." It's the plot of a movie that already exists. The crowd boos with delight.`,g:`"Picture it. A lone cop. One last job. The city needs him, but he doesn't need the city." He lowers the sunglasses. "Spring. Wide release." It's the plot of a movie that already exists. The crowd boos with delight.`,no:`He lowers the sunglasses. "My next film. A man. A plan. A — a car commercial, basically." He forgets the plot halfway through and starts describing a commercial.`,b:`"In my next film, I play a man who — who is in a movie. And there's a twist. I won't spoil the twist. I don't know the twist."`},
  {t:"Thank the Academy",s:'mic',d:.05,p:2,ok:`He clutches an imaginary statue. "I want to thank the Academy, my agent, and all of you — the little people." There is no award. Incredible heat.`,g:`He pulls out a folded speech. "I want to thank the Academy. My agent. My agent's other client. And all of you — the little people. So little. From up here." Eleven minutes. Incredible heat.`,no:`He unfolds a speech. "First, my agent, Gary. Second, Gary's assistant. Third—" The music plays him off. Like at the real Oscars.`,b:`He thanks the Academy and accidentally reads his grocery list. "...and almond milk." The music plays him off.`}]}},
{k:'teacher',old:1,n:'Substitute Teacher Ms. Pembrook',g:'F',st:'te',al:'h',tier:'prospect',mic:6,bio:"Takes attendance before every match. Will not start until everyone in the arena is seated and quiet.",
 m:{t:"{A} blows a whistle and informs {B} that they are being sent to the principal's office.",ch:[
  {t:"Give {B} detention in a surfboard stretch",s:'ring',d:.1,st:.5,heat:8,ok:"{B} learns a valuable lesson about respecting substitutes.",no:"{B} asks for a hall pass and escapes."},
  {t:"Hand out a pop quiz mid-match",s:'mic',d:.1,st:.25,popA:2,ok:"{B} fails. Visibly shaken.",no:"{B} gets a perfect score. {A} demands to see their work."}]},
 p:{t:"{A} walks to the ring with a clipboard and begins taking attendance.",ch:[
  {key:1,t:"Mark the entire front row absent",s:'mic',d:.05,p:3,ok:`She runs a pen down her clipboard. "Front row. Absent. Absent. Absent." They are present. They are furious. Beautiful heat.`,g:`"Front row." She looks up, slowly. "Absent. All of you. I can see you. You're absent." She makes a mark. Beautiful heat.`,no:`She looks at the front row. "Front row: absent." The front row yells "HERE!" in unison. Checkmate.`,b:`She reads the roll. "Jessica? Jason? Jasper— Jasmine?" Every name, mispronounced. The front row corrects her, in unison.`},
  {t:"Announce that there will be a test on Friday",s:'mic',d:.1,p:2,ok:`"There will be a test on Friday. No phones." Twenty thousand people groan at once.`,g:`"There will be a test on Friday." A pause. "It is cumulative." Twenty thousand people groan at once.`,no:`She taps the clipboard. "Test. Friday." Nobody believes her. It's Tuesday.`,b:`"There will be a test! On... Friday. Tomorrow." It's Tuesday. Nobody believes her.`}]}},
{k:'trophy',old:1,n:'The Human Participation Trophy',g:'M',st:'br',al:'f',tier:'prospect',pop:8,bio:"Has never won a match. Gets a trophy after every single one anyway. The fans adore him for it.",
 m:{t:"{A} is losing badly, but a ringside attendant is already polishing a trophy for them.",ch:[
  {t:"Fight on — everyone's a winner",s:'pop',d:.15,st:.75,popA:3,ok:"'YOU TRIED YOUR BEST' chants shake the building.",no:"They lost. They still get the trophy."},
  {t:"Hit {B} with the trophy",loseOk:'dq',dq:1,s:'luck',d:.05,st:.25,heat:10,ok:"Disqualified. Still gets the trophy.",no:"The trophy is plastic. It breaks. Tears."}]},
 p:{t:"{A} comes out clutching a shelf full of trophies to thunderous applause.",ch:[
  {key:1,t:"Thank every opponent who ever beat them",s:'pop',d:.05,p:4,ok:`He holds up a trophy. "To everyone who ever beat me: thank you. You made me." The crowd cheers every name.`,g:`He goes down the list, every opponent who ever beat him, and gives each one a trophy-shaped thank you. "And you, Gerald. You were the hardest loss." The crowd cheers every name.`,no:`He unrolls a list. "Thank you, Kevin. Thank you, other Kevin. Thank you—" The list is so long the show goes to commercial.`,b:`He starts the list. "Thank you, Rob. Thank you, Dana. Thank you, — sorry — Tony—" He starts crying at number three. The show goes to commercial.`},
  {t:"Promise that someday they'll win one for real",s:'mic',d:.1,p:3,ok:`"Someday, I'm going to win one for real. And you'll be here." Not a dry eye in the house.`,g:`He sets the trophies down one by one. "These are for trying. Someday, I'm going to win one for winning." His voice catches. "And I'll still bring these." Not a dry eye in the house.`,no:`He looks at the trophies. "Someday one of these will be for winning." The crowd isn't sure they believe it either.`,b:`"Someday I'll win! Probably. Eventually. Statistically." The crowd isn't sure they believe it.`}]}},
{k:'posh',old:1,n:'Sir Reginald Crumpet III',g:'M',st:'te',al:'h',tier:'bluechip',mic:6,bio:"Arrives by horse-drawn carriage. Wrestles with his pinky extended. Believes the ring is 'rather common'.",
 m:{t:"{A} pauses the match for afternoon tea, served by a butler who is already in the ring.",ch:[
  {t:"Finish the tea, then apply a very proper wristlock",s:'ring',d:.1,st:.5,heat:8,ok:"Civilised and devastating.",no:"{B} knocks the teacup over. An international incident."},
  {al:'h',t:"Have the butler trip {B}",s:'luck',d:.05,st:.5,heat:12,ok:"The butler does it without changing his expression. Chilling.",no:"The butler refuses. He has standards."}]},
 p:{t:"A trumpet fanfare plays. {A} is carried to the ring on a velvet chair.",ch:[
  {key:1,t:"Refer to the crowd as 'the peasantry'",s:'mic',d:.05,p:3,ok:`"Good evening, peasantry." The peasantry is outraged.`,g:`He sniffs the air. "Ah. The peasantry." A thin smile. "Do keep your hands where I can see them. And your smells where I cannot." The peasantry is outraged.`,no:`He sniffs. "Good evening, peasantry." Silence. Somebody shouts "What's a peasantry?" The insult misses.`,b:`"Good evening, peasants. Peasantry. Pheasants." The peasantry laughs at him.`},
  {t:"Challenge anyone to a duel, pistols optional",s:'mic',d:.1,p:2,ok:`"I challenge anyone to a duel! Pistols optional." Nobody accepts. He declares victory by default.`,g:`He removes one glove and slaps the ring post with it. "I challenge any of you to a duel. Pistols optional. Dignity required." Nobody accepts. He declares victory by default.`,no:`He removes a glove. "I challenge anyone to a duel!" Someone in the crowd shouts "I accept!" He suddenly remembers a prior engagement. "Ah. Tuesday. Alas."`,b:`He swings the glove and slaps himself. "Ow. I — I challenge anyone!" Someone accepts. "Ah. Prior engagement."`}]}},
{k:'hr',old:1,n:'Brenda from HR',g:'F',st:'pw',al:'h',tier:'prospect',ring:4,bio:"Files a formal complaint against every opponent. Has a disturbing number of forms.",
 m:{t:"{A} pulls a form from their gear and begins filing a complaint against {B} mid-match.",ch:[
  {t:"Suspend {B} with a powerbomb 'pending review'",s:'ring',d:.1,st:.5,heat:10,ok:"The review found {B} guilty.",no:"{B} reports {A} to a higher HR department."},
  {t:"Schedule a mandatory sensitivity seminar right now",s:'mic',d:.1,st:.25,popA:2,ok:"{B} has to sit through a slideshow. The crowd boos gleefully.",no:"The projector doesn't work."}]},
 p:{t:"{A} walks out with a stack of forms and a lanyard.",ch:[
  {key:1,t:"Read the locker room's complaints aloud",s:'mic',d:.1,p:3,ok:`She adjusts her lanyard. "Complaint one: 'Someone keeps stealing my towels.' We know who you are." The locker room will never feel safe again.`,g:`She adjusts her lanyard. "Complaint 47-B: 'Someone keeps stealing my yogurt.' We know who you are. Complaint 47-C: also the yogurt." The locker room will never feel safe again.`,no:`She reads from the folder. "Complaint about Brenda. Complaint about Brenda. Complaint about Brenda's yogurt." Most of them are about Brenda.`,b:`She reads the first complaint. "'The HR person is'— I'll skip that one." So is the second. Most of the rest are about Brenda.`},
  {t:"Announce a mandatory team-building exercise",s:'mic',d:.05,p:2,ok:`She taps the clipboard. "Mandatory team-building. Trust falls. Saturday." Nobody wants to do trust falls. The crowd boos.`,g:`"Mandatory team-building. Saturday. Trust falls." She looks up. "Attendance is tracked. Not attending is also tracked." The crowd boos.`,no:`She smiles. "Team-building! Saturday!" Nobody shows up to it.`,b:`She announces it. "Team-building on Sunday. Monday. At the — the place." Nobody shows up to it.`}]}},
{k:'doll',old:1,n:'The Haunted Victorian Doll',g:'F',st:'fl',al:'h',tier:'bluechip',pop:6,bio:"Found in an attic in 1893. Never blinks. The lights flicker whenever she wins.",
 m:{t:"The lights flicker. When they come back, {A} is standing directly behind {B}. Nobody saw her move.",ch:[
  {t:"Tilt her head slowly, then strike",s:'pop',d:.1,st:.75,heat:10,ok:"The crowd screams. Genuinely.",no:"{B} turns around first. Awkward for everyone."},
  {t:"Sit perfectly still until {B} gets too close",s:'luck',d:.05,st:.5,heat:8,ok:"{B} leans in and gets rolled up. Terrifying.",no:"{B} just leaves her there."}]},
 p:{t:"A music box plays. {A} is wheeled to the ring in a glass case.",ch:[
  {key:1,t:"Say nothing and let the music box play",s:'pop',d:.1,p:4,ok:`{A} says nothing and lets the music box play. Twenty thousand people are too scared to boo.`,g:`The music box plays. {A} doesn't move. The tune slows, almost stops, and the lights in the upper deck go out one section at a time. Twenty thousand people are too scared to boo.`,no:`The music box runs down. Silence.`,b:`The music box plays the wrong song — a cheerful one. Nobody's scared. It runs down.`},
  {t:"Whisper a name from the locker room",s:'mic',d:.1,p:3,ok:`A whisper, barely picked up by the mic: "...I know your name." Somewhere in the back, a wrestler screams.`,g:`A whisper, barely picked up by the mic: "...Come and play." Somewhere in the back, a wrestler screams, and the lights flicker once.`,no:`{A} whispers. "...You." Nobody hears it.`,b:`{A} whispers. "...Kevin?" Nobody on the roster is named Kevin. Nobody screams.`}]}},
{k:'pirate',old:1,n:'Captain Seagull',g:'M',st:'br',al:'f',tier:'prospect',pop:5,bio:"A fearsome pirate who is afraid of water, boats and, to a lesser degree, seagulls.",
 m:{t:"{A} hears a seagull noise from the crowd and freezes in terror.",ch:[
  {t:"Overcome the fear and hit a flying elbow",s:'pop',d:.15,st:.75,popA:3,ok:"The crowd roars. A pirate reborn!",no:"The seagull noise happens again. He's out."},
  {t:"Make {B} walk the plank off the apron",s:'ring',d:.1,st:.5,ok:"{B} takes a long fall to the floor. Arrrr.",no:"{B} refuses to walk the plank."}]},
 p:{t:"{A} swaggers out in full pirate gear and immediately gets seasick on the ramp.",ch:[
  {key:1,t:"Promise to lead the fans to buried treasure",s:'mic',d:.1,p:3,ok:`He points a cutlass at the crowd. "Follow me to the treasure, me hearties!" The treasure is a box of t-shirts. The fans are thrilled.`,g:`"Follow me, me hearties! Treasure awaits!" He unrolls a map, points at the merch stand. The treasure is a box of t-shirts. The fans are thrilled.`,no:`He pats his coat. "The map! Where's the map?" He can't find it.`,b:`He unrolls the map. "X marks the — this is a menu." He can't find the real one.`},
  {t:"Lead the crowd in a sea shanty",s:'pop',d:.05,p:3,ok:`He raises a tankard. "Haul away, me hearties! Sing!" The whole arena sings. Pure joy.`,g:`He starts alone, in a low gravel. "Oh, the ring was rough and the ropes were tight—" By the second verse the whole building is stomping in time. Pure joy.`,no:`He raises a tankard. "Sing with me! Oh, the — come on, you know it!" Nobody knows the words.`,b:`He starts. "Oh, the sea was — the sea had — something about a whale?" He forgets the words himself. Nobody knows them either.`}]}},
{k:'vamp',old:1,n:'Discount Dracula',g:'M',st:'sh',al:'h',tier:'prospect',bio:"An ancient creature of the night who is scared of the dark, allergic to garlic and deeply in debt.",
 m:{t:"{A} lunges for {B}'s neck and gets distracted by their own reflection in the ring post.",ch:[
  {t:"Recover with a menacing cape swirl",s:'pop',d:.1,st:.5,popA:2,ok:"The cape is magnificent. The crowd hisses.",no:"The cape gets caught in the ropes."},
  {al:'h',t:"Throw 'garlic' (a breadstick) at {B}",s:'luck',d:.05,st:.25,heat:10,ok:"{B} is confused enough to be pinned.",no:"{B} eats the breadstick."}]},
 p:{t:"The lights go out. {A} asks, quite urgently, for them to be turned back on.",ch:[
  {key:1,t:"Declare that the night belongs to him",s:'mic',d:.1,p:3,ok:`"The night belongs to me!" It's 8:15pm. The crowd boos anyway.`,g:`"The night belongs to me." He checks his watch. "Starting at nine. I need a little rest first." It's 8:15pm. The crowd boos anyway.`,no:`He spreads his cape. "The night belongs to me!" Someone points out it's still light outside.`,b:`"The night is mine!" A fan points to a window. Sunlight. He hides behind the ring post.`},
  {t:"Hypnotise a fan in the front row",s:'luck',d:.1,p:3,ok:`He swings a pocket watch. "You will cheer for me." It works?! The fan cheers for {A}. Everyone is unsettled.`,g:`He fixes the fan with a stare and swings a pocket watch. "You will cheer... for me." The fan slowly stands up and cheers. It works?! Everyone is unsettled.`,no:`He swings the watch. "Look into my eyes. You are getting sleepy—" The fan just laughs.`,b:`He swings the pocket watch. "You are getting very—" It flies off the chain. The fan just laughs.`}]}},
{k:'grandma',old:1,n:'Grandma Knuckles',g:'F',st:'br',al:'f',tier:'prospect',ring:-2,pop:10,bio:"Seventy-two years old. Undefeated at bingo. Has hit more people with a purse than anyone alive.",
 m:{t:"{A} reaches into her purse. The whole building knows what's coming.",ch:[
  {t:"Purse shot!",dq:1,s:'luck',d:.05,st:.5,popA:3,heat:8,ok:"The ref 'didn't see it'. The crowd erupts.",no:"The ref saw it. Grandma doesn't care."},
  {t:"Pull out a hard candy and offer {B} one",s:'pop',d:.05,st:.25,popA:2,ok:"{B} accepts. Roll-up. Three count.",no:"{B} declines. Grandma is offended."}]},
 p:{t:"{A} slowly makes her way down the ramp with a walker, which she then throws at the ring.",ch:[
  {key:1,t:"Tell the locker room they're all too soft",s:'mic',d:.1,p:4,ok:`"You're all soft! Every one of you in that locker room!" The crowd agrees completely.`,g:`"In my day we wrestled in a barn. On fire. Uphill." She points at the back with her walker. "You're soft. All of you. Like bread." The crowd agrees completely.`,no:`She leans on her walker. "Soft! All of you! Back in 1968, we had a fella named Earl—" She drifts into a story about 1968.`,b:`She points. "Soft! Like in '68, when — or was it '71? Earl would know. Earl had a boat—" A story about a man named Earl.`},
  {t:"Pinch the ring announcer's cheek",s:'pop',d:0,p:3,ok:`She pinches the announcer's cheek. "Look at this face! Eat something, dear." He's embarrassed. The crowd loves it.`,g:`She pinches the announcer's cheek. "Such a good boy. Eat something." She hands him a hard candy from her purse. He's embarrassed. The crowd loves it.`,no:`She reaches for his cheek. "Come here, sweetie—" He dodges. "Well. I never." She's disappointed in him.`,b:`She pinches a cheek. "Such a good boy!" It's the referee. He's confused. She's disappointed in herself.`}]}},
{k:'influencer',old:1,n:"Like & Subscribe Kayleigh",g:'F',st:'sh',al:'h',tier:'prospect',mic:5,bio:"Films every match on a ring light attached to her head. Four million followers. Nine of them are real.",
 m:{t:"{A} stops to film a quick vertical video for her followers — with {B} still in the ring.",ch:[
  {t:"Film a reaction video of {B}'s pain",s:'mic',d:.05,st:.25,heat:10,ok:"The video goes viral. The crowd is disgusted.",no:"The ring light blinds her."},
  {t:"Ask chat what move to do next",loseNo:'pin',s:'luck',d:.1,st:.5,popA:2,ok:"Chat says 'moonsault'. She actually hits it.",no:"Chat says 'lose'. She loses."}]},
 p:{t:"{A} livestreams her entrance, narrating to her followers.",ch:[
  {key:1,t:"Remind everyone to like and subscribe",s:'mic',d:.05,p:3,ok:`She holds up her phone. "Like and subscribe, everybody! Smash that button!" The crowd chants "NO." Great engagement.`,g:`She turns to her phone, then to the crowd. "If you're watching live, hit that like. If you're here, hit it twice." The crowd chants "NO." Great engagement.`,no:`She holds up her phone. "Hi, fam! Drop a comment—" The stream crashes.`,b:`She holds up her phone. "Like and subscribe! ...Wait. Am I live? I'm not live." The stream was never on.`},
  {t:"Announce a new merch drop",s:'pop',d:.1,p:2,ok:`She holds up a hoodie. "New merch. Tonight only. One eighty." It costs $180. Pure villainy.`,g:`"New drop, tonight only. Hoodie. One eighty." She smiles. "Plus shipping. Plus my respect." It's a hoodie that costs $180. Pure villainy.`,no:`She points at the screen. "Link in bio! Go, go, go!" The website crashes.`,b:`She holds up the hoodie. "Use code — oh, that's the free one. Don't use that." The website crashes.`}]}},
{k:'cop',old:1,n:'Mall Cop Marv',g:'M',st:'pw',al:'f',tier:'prospect',bio:"Takes mall security extremely seriously. Rides a Segway to the ring. Has never made an arrest.",
 m:{t:"{A} blows a whistle and informs {B} that they are loitering in the ring.",ch:[
  {t:"Escort {B} off the premises with a powerslam",s:'ring',d:.1,st:.5,popA:2,ok:"Order is restored to the food court.",no:"{B} shows a receipt and is allowed to stay."},
  {t:"Chase {B} around the ring on the Segway",s:'luck',d:.1,st:.25,popA:2,ok:"He catches them. Barely.",no:"The Segway battery dies."}]},
 p:{t:"{A} rides a Segway down the ramp at a stately four miles an hour.",ch:[
  {key:1,t:"Remind the fans that running is not allowed",s:'mic',d:.05,p:3,ok:`He blows a whistle. "No running! Walking only!" The crowd walks, briskly, to the concessions. Order!`,g:`"Walking. Is. Encouraged." He points at a kid. "You. Slower." The crowd walks, briskly, to the concessions. Order!`,no:`He blows the whistle. "Walk! WALK!" Everyone runs anyway.`,b:`He rolls forward on the Segway. "No running in the — whoa—" He falls off. Everyone runs anyway.`},
  {t:"Check everyone's bags for outside snacks",s:'pop',d:.1,p:2,ok:`He holds up a pretzel. "Outside food. Confiscated." The crowd cheers.`,g:`He holds the pretzel up to the light, examines it, and slides it into an evidence bag. "Outside snacks. Not on my watch." The crowd cheers.`,no:`He holds up the pretzel. "Confiscated." Then takes a bite. The crowd boos.`,b:`He digs through a bag. "Aha! Contraband!" It's his own lunch. The crowd boos.`}]}},
{k:'nap',old:1,n:'Mister Nap',g:'M',st:'te',al:'f',tier:'bluechip',mic:-5,bio:"The most talented technical wrestler of his generation. Falls asleep in rest holds. Sometimes in his own.",
 m:{t:"{A} locks in a rest hold… and starts snoring.",ch:[
  {t:"Wake up and roll into a submission",loseNo:'pin',s:'ring',d:.15,st:.75,popA:2,ok:"He was never asleep! Or was he? The crowd goes wild.",no:"He was asleep. The ref counts three."},
  {t:"Let the crowd wake him with a chant",s:'pop',d:.05,st:.5,popA:3,ok:"'WAKE UP NAP!' He springs to life.",no:"He rolls over."}]},
 p:{t:"{A} walks out in pajamas holding a pillow.",ch:[
  {key:1,t:"Try to cut a promo before dozing off",s:'mic',d:.15,p:3,ok:`He blinks slowly. "Next week... I'm gonna... beat... everybody." He gets through it before dozing off. The crowd applauds his effort.`,g:`He gets through the whole promo, eyes half-shut, every word clear. On the last one, he yawns into the mic. "...goodnight." The crowd applauds his effort.`,no:`He raises the mic. "This Sunday, I'm going to—" A yawn. "—going to—" Asleep by the third sentence.`,b:`He raises the mic. "Hello every—" Asleep by the first sentence. Snoring by the second.`},
  {t:"Tuck in the front row",s:'pop',d:.05,p:3,ok:`He pulls a blanket over the front row. "Rest up. Big show." The coziest segment in history.`,g:`He tucks the front row in one by one, then fluffs the pillow under a kid's head. "Sweet dreams. Big match later." The coziest segment in history.`,no:`He drapes a blanket over the front row. "Nap time." They don't want to be tucked in.`,b:`He tucks in the front row. "Sweet dreams... sweet... zzz." He falls asleep halfway down. They don't want to be tucked in.`}]}},
{k:'weather',old:1,n:'Stormy Pete, Channel 7 Weather',g:'M',st:'sh',al:'f',tier:'prospect',mic:8,bio:"Delivers a full forecast before every match. Has never once been right.",
 m:{t:"{A} pauses the match to point at a green screen that isn't there.",ch:[
  {t:"Forecast a 90% chance of a clothesline",s:'mic',d:.05,st:.5,popA:2,ok:"The forecast is correct for the first time. Historic.",no:"Unseasonably sunny. {B} hits him first."},
  {t:"Hit a move called the Cold Front",s:'ring',d:.1,st:.5,ok:"It's just a dropkick, but the name sells it.",no:"The cold front stalls over the apron."}]},
 p:{t:"{A} walks out holding a clicker and gestures at an imaginary weather map.",ch:[
  {key:1,t:"Deliver the five-day forecast",s:'mic',d:.1,p:3,ok:`He clicks the forecast. "Monday, sunny. Tuesday, scattered losses for my opponents." Warm and informative. The crowd applauds the barometric pressure.`,g:`"Monday: heavy. Tuesday: heavier. Wednesday: pressure building. Thursday, Friday — storm." He lowers the clicker. "Storm's name is me." The crowd applauds the barometric pressure.`,no:`He clicks the forecast. "Clear skies all week!" It's raining in the building.`,b:`He clicks the forecast. "And in Phoenix, a high of — this isn't Phoenix." It's raining in the building.`},
  {t:"Issue a severe storm warning for his opponents",s:'mic',d:.1,p:3,ok:`He points at the back. "Severe storm warning for everyone in that locker room. Take shelter." The locker room takes shelter.`,g:`"This is a severe weather alert for everyone in that locker room." He points at the back. "Seek shelter. Stay away from windows. And me." The locker room takes shelter.`,no:`He points at the back. "Severe storm warning! Seek shelter!" Nobody evacuates.`,b:`He points at the back. "Storm warning! Severe sunshine expected." Nobody evacuates.`}]}},
{k:'box',old:1,n:'The Box',g:'M',st:'pw',al:'h',tier:'bluechip',ring:4,mic:-15,bio:"A cardboard box that walks to the ring. Nobody knows who is inside. The contract was signed with a crayon.",
 m:{t:"{A} sits down in the corner and becomes completely motionless. It is, at this point, just a box.",ch:[
  {t:"Wait for {B} to check inside, then strike",s:'luck',d:.05,st:.75,heat:10,ok:"{B} peeks in. {B} is never the same.",no:"{B} just leaves the box alone."},
  {t:"Tip over and roll across the ring onto {B}",s:'ring',d:.1,st:.5,ok:"A shocking amount of force for a box.",no:"The box rolls out of the ring."}]},
 p:{t:"A large cardboard box is placed in the ring. It has a mic taped to the side.",ch:[
  {key:1,t:"Stay completely silent",s:'pop',d:.1,p:4,ok:`The box stays completely silent. The crowd chants "BOX! BOX! BOX!"`,g:`The box says nothing. Ten seconds. A minute. Then, very slightly, it turns to face the hard camera. The crowd chants "BOX! BOX! BOX!"`,no:`The crowd is bored of the box.`,b:`The box stays silent, but sneezes. The crowd is bored of the box.`},
  {t:"A small hand emerges and waves",s:'luck',d:.05,p:3,ok:`A small hand emerges and waves. The crowd screams. Who is in there?!`,g:`A small hand emerges, waves once, points at the camera, and gives a thumbs-down. Then goes back in. The crowd screams. Who is in there?!`,no:`The hand goes back in.`,b:`A hand emerges, waves, and drops a phone out of the box. The hand goes back in, embarrassed.`}]}},
{k:'chef',old:1,n:'Chef Remy Flambé',g:'M',st:'sh',al:'h',tier:'prospect',bio:"Classically trained. Cooks a three-course meal at ringside during his matches. Nobody is allowed to eat it.",
 m:{t:"{A} ducks out to the ringside stove to check on the soufflé.",ch:[
  {t:"Serve {B} a knuckle sandwich",s:'ring',d:.05,st:.5,heat:6,ok:"Perfectly seasoned.",no:"{B} sends it back to the kitchen."},
  {al:'h',t:"Throw flour in {B}'s eyes",s:'luck',d:.05,st:.5,heat:12,ok:"{B} is blinded. Delicious villainy.",no:"The flour goes everywhere. Including {A}."}]},
 p:{t:"{A} wheels a kitchen station down the ramp and lights a pan on fire.",ch:[
  {key:1,t:"Call the fans' taste in food 'pedestrian'",s:'mic',d:.05,p:3,ok:`He sniffs the front row's nachos. "Pedestrian." The crowd is personally offended. Great heat.`,g:`He looks at the nachos in the front row like they've insulted his mother. "This? This is what you put in your body? It is pedestrian. You are pedestrian." The crowd is personally offended.`,no:`He wrinkles his nose. "Your food is pedestrian." A fan shouts "Yeah, it is!" The fans agree, honestly.`,b:`He sneers. "Pedestrian." Then eats a nacho. "...Pedestrian, but fine." The fans agree, honestly.`},
  {t:"Eat the entire meal in front of the crowd",s:'luck',d:0,p:2,ok:`He sits at ringside with a plate. "Watch and learn." He eats the entire meal in front of the crowd. The boos are hungry and angry.`,g:`He plates all three courses, sits at ringside, and eats every bite while staring at the front row. "Magnifique." The boos are hungry and angry.`,no:`He takes a big bite. "Mmm — HOT. Hot hot hot." He burns his tongue.`,b:`He takes a bite. "Ow! Hot!" Then the flambé catches his apron. "Fire! FIRE!"`}]}},
{k:'spell',old:1,n:'Two-Time Spelling Bee Champion Priya Anand',g:'F',st:'te',al:'f',tier:'bluechip',mic:4,bio:"Spells the name of every move before she does it. The referee is required to confirm the spelling.",
 m:{t:"{A} announces she's going to do a move and asks for its definition and use in a sentence.",ch:[
  {t:"Spell 'B-R-I-D-G-I-N-G S-U-P-L-E-X' and hit it",s:'ring',d:.15,st:.75,popA:3,ok:"Correct! Three count!",no:"She spells it wrong and loses her concentration."},
  {t:"Challenge {B} to spell their own finisher",s:'mic',d:.1,st:.25,popA:2,ok:"{B} can't. Devastating psychological damage.",no:"{B} spells it perfectly. Humiliating."}]},
 p:{t:"{A} walks out holding a dictionary and a trophy from 2009.",ch:[
  {key:1,t:"Spell out the name of her next opponent — slowly",s:'mic',d:.1,p:3,ok:`She points at the back. "Your name. B. E. A. T. E. N." The crowd spells along. Every letter lands.`,g:`She looks at her opponent. "Your name. Please." Then spells it, slowly, letter by letter, while the crowd spells along. "Correct." Every letter lands.`,no:`She spells it out. "K. N. —" Their name has a silent letter. Chaos.`,b:`She spells the name. "S. M. I. T. H. E." The crowd spells it right, loudly. "Can I get the definition?"`},
  {t:"Correct the crowd's signs",s:'pop',d:.05,p:2,ok:`She walks the barricade with a red pen. "Its, not it's. Fixed it for you." The crowd appreciates the feedback. Mostly.`,g:`She walks the barricade with a red pen. "Its. Not it's. 'Your' — no. Close. Good effort." The crowd appreciates the feedback. Mostly.`,no:`She points at a sign. "That's wrong. It's 'your,' not—" The signs were correct. She's shaken.`,b:`She corrects a sign. "There. Fixed." The fan shows her it was right before. "Oh." She's shaken.`}]}},
{k:'chiro',old:1,n:'The Unlicensed Chiropractor',g:'M',st:'te',al:'h',tier:'prospect',bio:"Cracks backs. Nobody asked. His diploma is written on a napkin.",
 m:{t:"{A} grabs {B} in a bear hug and announces that it's 'just an adjustment'.",ch:[
  {t:"Crack {B}'s back until something pops",s:'ring',d:.1,st:.5,heat:10,ok:"{B} feels, somehow, better. Then {A} pins them.",no:"Nothing pops. Awkward silence."},
  {al:'h',t:"Offer {B} a free consultation — then attack",s:'luck',d:.05,st:.5,heat:12,ok:"{B} fell for it. Classic malpractice.",no:"{B} checks his credentials first."}]},
 p:{t:"{A} walks out with a portable massage table and a stack of business cards.",ch:[
  {key:1,t:"Offer the front row a free adjustment",s:'mic',d:.1,p:3,ok:`He cracks his knuckles. "Free adjustment for the front row!" Security has to step in. The crowd boos gleefully.`,g:`He cracks his knuckles and points at the front row. "Free adjustment. You. You're crooked. I can hear it from here." Security has to step in. The crowd boos gleefully.`,no:`He beckons. "Free adjustment! Anyone?" Nobody volunteers.`,b:`He points. "Free adjustment, step right — ohhh, my back." He cracks his own back and has to lie down. Nobody volunteers.`},
  {t:"Announce that he's now accepting insurance",s:'mic',d:.05,p:2,ok:`He raises a finger. "Big news. I now accept insurance." He doesn't. The crowd is outraged.`,g:`"Big news. I now accept insurance." A pause. "Not yours. But insurance." He's not. The crowd is outraged.`,no:`He beams. "I take insurance now!" Nobody believes him anyway.`,b:`He reads off a card. "I accept insurance, policy number four, seven, nine—" That's his own. Nobody believes him anyway.`}]}},
{k:'pigeon',old:1,n:'Lord Pigeon',g:'M',st:'fl',al:'h',tier:'prospect',pop:5,bio:"Claims to command every pigeon in the city. Has one pigeon. Its name is Gerald.",
 m:{t:"{A} lets out a shrill whistle. Somewhere in the rafters, a single pigeon stirs.",ch:[
  {t:"Fly off the top rope like the pigeons taught him",s:'ring',d:.15,st:.75,fat:5,ok:"A majestic dive. Gerald would be proud.",no:"Pigeons are not known for their landing."},
  {al:'h',t:"Have Gerald distract the referee",s:'luck',d:.1,st:.5,heat:10,ok:"Gerald lands on the ref's head. {A} cheats freely.",no:"Gerald doesn't show up. Gerald never shows up."}]},
 p:{t:"{A} walks out with a pigeon on his shoulder and demands silence for Gerald.",ch:[
  {key:1,t:"Explain the pigeon hierarchy",s:'mic',d:.1,p:3,ok:`He strokes the pigeon. "At the top: Gerald. Then the council. Then you." It's weirdly detailed. The crowd is hooked.`,g:`"At the top: Gerald. Below Gerald: the council of Gerald. Below that: everyone else." He strokes the pigeon. "You are below everyone else." It's weirdly detailed. The crowd is hooked.`,no:`He raises the pigeon. "Gerald sits at the top, and below Gerald—" Gerald flies away mid-speech.`,b:`He raises the pigeon. "Gerald is number three — no, two —" Gerald flies away mid-speech.`},
  {t:"Threaten the city's statues",s:'mic',d:.05,p:2,ok:`He leans into the mic. "Every statue in this city. My birds know where they are." The crowd boos on behalf of the statues.`,g:`"Every statue in this city. I know where they are. My birds know where they are." He leans in. "Sleep well." The crowd boos on behalf of the statues.`,no:`He points outside. "Your statues are next!" Nobody knows why this is a threat.`,b:`He points outside. "Watch out, Lincoln Memorial!" It's the wrong city. Nobody knows why this is a threat.`}]}},
{k:'karaoke',old:1,n:'Karaoke Katie',g:'F',st:'sh',al:'f',tier:'prospect',mic:6,pop:6,bio:"Sings her own entrance music, live, badly, every single time. The crowd sings along anyway.",
 m:{t:"{A} grabs the ring announcer's mic and starts singing mid-match.",ch:[
  {t:"Hit a big move on the high note",s:'pop',d:.1,st:.5,popA:3,ok:"The note is flat. The move is perfect. The crowd loves both.",no:"She holds the note too long and {B} rolls her up."},
  {t:"Get the whole crowd singing to rally",s:'pop',d:.05,st:.5,popA:2,ok:"Twenty thousand people sing a power ballad. The comeback is on.",no:"The crowd picks a different song."}]},
 p:{t:"{A} comes out singing her own theme, badly, and the crowd sings louder than her.",ch:[
  {key:1,t:"Hand the mic to a fan for a duet",s:'pop',d:.05,p:4,ok:`She hands a fan the mic. "Take it away!" The fan is incredible. A star is born.`,g:`She hands the mic to a fan. "Your verse." The fan nails it. She stops singing and just points at them. "Them!" A star is born.`,no:`She hands a fan the mic. "Your turn!" The fan freezes. "Okay, I've got it!" {A} finishes the song alone.`,b:`She hands a fan the mic. "Sing with me!" The fan sings a completely different song. They both keep going. Nobody wins.`},
  {t:"Dedicate a song to her next opponent",s:'mic',d:.1,p:3,ok:`She points at the camera. "This one's for my next opponent." It's a breakup song. Brutal.`,g:`"This one's for you." She sings it slow, right into the camera, every word a breakup. On the last line she points. "We're done." Brutal.`,no:`She raises the mic. "This one's for you. Ahem. 'We were never—' uh. Hmm." She forgets the lyrics.`,b:`She raises the mic. "This is for my next opponent. 'I will always love—' wait." It's a love song. The opponent blushes.`}]}},
{k:'timeshare',n:'Timeshare Terry',g:'M',st:'br',al:'h',tier:'prospect',mic:6,bio:"Won't wrestle anyone until they've sat through a ninety-minute presentation. There is a free buffet.",
 m:{t:"{A} pulls out a laminated brochure and tries to sell {B} a week in a condo mid-match.",ch:[
  {t:"Close the deal with a lariat",s:'ring',d:.1,st:.5,heat:8,ok:"{B} signs. There's no cancellation policy.",no:"{B} says they need to think about it."},
  {al:'h',t:"Hide a foreign object in the brochure",s:'luck',d:.05,st:.5,heat:12,ok:"The fine print was a roll of quarters.",no:"The ref reads the fine print."}]},
 p:{t:"{A} sets up a small folding table in the ring with a bowl of mints.",ch:[
  {key:1,t:"Pitch the crowd a 'limited-time opportunity'",s:'mic',d:.1,p:3,ok:`He opens a briefcase. "Ninety minutes. That's all I ask. A limited-time opportunity." The crowd is furious. Several people take brochures anyway.`,g:`"I'm not selling anything. I'm offering you an opportunity." He taps the bowl of mints. "Ninety minutes. That's all I ask." The crowd is furious. Several people take brochures anyway.`,no:`He opens a brochure. "Let me tell you about a beautiful property—" The crowd walks out to the concessions.`,b:`He opens the brochure. "This incredible opportunity is for — a — what is this for?" The crowd walks out to the concessions.`},
  {t:"Offer the locker room a free weekend getaway",s:'mic',d:.05,p:2,ok:`He points at the back. "Free weekend getaway for the whole locker room!" There's a catch. There's always a catch.`,g:`"Free weekend getaway for the entire locker room." He smiles. "All you have to do is listen." There's a catch. There's always a catch.`,no:`He smiles wide. "A free weekend! All you have to do—" Nobody takes the bait.`,b:`He reads the card. "Ninety-minute presentation required. Also, free weekend!" Nobody takes the bait.`}]}},
{k:'jeff',old:1,n:'Jeff',g:'M',st:'te',al:'f',tier:'gen',mic:-12,pop:-4,bio:"Just Jeff. No gimmick. No catchphrase. No entrance music. Might be the most gifted wrestler in the world.",
 m:{t:"{A} just… wrestles. It's incredible. Nobody knows how to react.",ch:[
  {t:"Keep doing it",s:'ring',d:.1,st:.75,ok:"'JEFF! JEFF! JEFF!' The crowd has discovered him.",no:"He's too subtle for the crowd tonight."},
  {t:"Give a small thumbs up",s:'pop',d:.05,st:.25,popA:3,ok:"The most charisma Jeff has ever shown. The crowd explodes.",no:"Nobody sees it."}]},
 p:{t:"{A} walks to the ring in plain black trunks. There's no music.",ch:[
  {key:1,t:"Say 'Hi. I'm Jeff.'",s:'mic',d:.1,p:3,ok:`"Hi. I'm Jeff." The crowd chants "HI JEFF." A movement begins.`,g:`He takes the mic. Looks at the crowd. "Hi. I'm Jeff." Puts the mic down. The crowd chants "HI JEFF." A movement begins.`,no:`He takes the mic. "Hi. I'm Jeff." Silence. Jeff leaves.`,b:`"Hi. I'm —" A long pause. "Jeff." Silence. Jeff leaves.`},
  {t:"Do one perfect push-up and leave",s:'pop',d:.05,p:2,ok:`Jeff drops to the mat. One perfect push-up. "That's all." The crowd respects it.`,g:`One push-up. Perfect form. Chest to mat, back up, slow. He stands. "Jeff." Nods once and walks out. The crowd respects it.`,no:`Jeff does one push-up. "There." Nobody understands.`,b:`Jeff does one push-up, then a second. "Oops." Nobody understands what that means.`}]}},
/* ---- v98: Josh's gimmick list ---- */
{k:'dblmeat',n:'"Double Meat" Popeye Mulligan',g:'M',st:'pw',al:'f',tier:'prospect',pop:4,bio:"Orders everything double meat. Sandwiches, burritos, salads. Nobody has ever told him no.",
 m:{t:"{A} pulls a foil-wrapped sandwich out of his kneepad mid-match and takes a huge bite.",ch:[
  {t:"Power up on the double meat and hit a double powerbomb",s:'ring',d:.1,st:.5,popA:2,ok:"Two powerbombs. Double meat. The crowd gets it.",no:"Cramps. Should have waited thirty minutes."},
  {t:"Offer {B} the other half",s:'pop',d:.05,st:.25,popA:2,ok:"{B} takes it. For one beautiful moment, there is peace.",no:"{B} slaps it to the mat. The crowd gasps in horror."}]},
 p:{t:"{A} walks out holding a sandwich so tall he needs both hands.",ch:[
  {key:1,t:"Demand double meat on everything — the card, the show, the title",s:'mic',d:.1,p:3,ok:`He demands double meat on everything. "DOUBLE MEAT! DOUBLE MEAT!" shakes the building.`,g:`"Double meat on the card. Double meat on the show. Double meat —" he jabs a finger at the hard camera "— on the TITLES." "DOUBLE MEAT! DOUBLE MEAT!" shakes the building.`,no:`He raises a sandwich. "Double meat!" The crowd is just hungry now.`,b:`He raises a sandwich. "DOUBLE M—" He drops it. The crowd is just hungry now.`},
  {t:"Hand out sliders to the front row",s:'pop',d:.05,p:2,ok:`He hands out sliders. "Double meat for the front row!" The front row would run through a wall for him.`,g:`He walks the front row handing out sliders, double meat, one each, and gives the last one to a kid. "Don't tell your mom." The front row would run through a wall for him.`,no:`He tosses sliders to the front row. "Eat up!" Health code violation.`,b:`He hands out sliders. "One for you, one for — that was my dinner. Can I have one back?" Health code violation.`}]}},
{k:'seger1',n:'"Against the Wind" Dan Bath',g:'M',st:'br',al:'f',tier:'prospect',pal:'seger2',bio:"Charges to the ring every week, somehow always into a headwind — even indoors. Best friends with \"Hollywood Nights\" Bob Arlington.",
 m:{t:"A gust from the arena vents hits — {A} leans into it and keeps charging at {B}.",ch:[
  {t:"Run against the wind, straight into a shoulder tackle",s:'ring',d:.1,st:.5,popA:2,ok:"Nothing can stop him. Not even the air conditioning.",no:"The wind wins this one."},
  {t:"Point to the rafters and wait for the breeze to turn",s:'luck',d:.05,st:.25,ok:"It turns. So does the match.",no:"It doesn't. Long, awkward pause."}]},
 p:{t:"{A} walks out slowly, hair blowing back from a box fan someone set at the top of the ramp.",ch:[
  {key:1,t:"Talk about every mile he ran to get here",s:'mic',d:.1,p:3,ok:`He stares into the box fan. "Every mile. I ran every mile for you." Dads in the crowd are openly weeping.`,g:`"Two hundred miles. Uphill. In a headwind. Every one of them." He stares into the box fan. "And I'd run every one again for you." Dads in the crowd are openly weeping.`,no:`He leans on the ropes. "Mile one hundred twelve was the hard one. Mile one hundred thirteen—" Too many miles. The crowd drifts off.`,b:`He counts on his fingers. "Two hundred miles. Or three. It was a lot of miles." The crowd drifts off.`},
  {t:"Call out for Bob Arlington",s:'pop',d:.05,p:2,ok:`He cups his hands. "BOB! BOB ARLINGTON!" The whole building chants "BOB! BOB! BOB!"`,g:`He cups his hands to his mouth. "BOB!" Nothing. He waits. "BOB ARLINGTON!" The whole building chants "BOB! BOB! BOB!"`,no:`He cups his hands. "BOB!" Bob is stuck in traffic.`,b:`He cups his hands. "BOB ARLINGHAM!" Wrong name. Bob is stuck in traffic anyway.`}]}},
{k:'seger2',n:'"Hollywood Nights" Bob Arlington',g:'M',st:'sh',al:'f',tier:'prospect',mic:4,pal:'seger1',bio:"Spent one weekend in Hollywood in 1987. Has not stopped talking about it. Best friends with \"Against the Wind\" Dan Bath.",
 m:{t:"{A} stops to put on sunglasses in the middle of the match. It's 9 p.m. Indoors.",ch:[
  {t:"Hit a slow-motion, movie-style dropkick",s:'ring',d:.1,st:.5,popA:2,ok:"Somebody yell cut — that was perfect.",no:"Wrong take. Way too slow."},
  {t:"Wave to the 'producers' in the crowd",s:'pop',d:.05,st:.25,ok:"A guy in a beret waves back. The crowd loves it.",no:"Nobody here is a producer. Nobody."}]},
 p:{t:"{A} rolls into the arena in a convertible with the top down.",ch:[
  {key:1,t:"Tell the story of that one Hollywood night",s:'mic',d:.1,p:3,ok:`He looks into the distance. "1987. Hollywood. The top was down." It's a great story. It's always a great story.`,g:`"It was 1987. The top was down. The lights were on." He looks into the distance. "And I never saw her again." It's a great story. It's always a great story.`,no:`He leans on the ropes. "So it's 1987, I'm in Hollywood—" A fan yells "We know!" The crowd has heard it four times this month.`,b:`He starts. "And then she married Bob Arlington." The crowd corrects him with a loud "NO, SHE DIDN'T!" They've heard it four times this month.`},
  {t:"Sign headshots of himself for the front row",s:'pop',d:.05,p:2,ok:`He signs a headshot. "To Linda. Keep the top down." The front row is framing them.`,g:`He signs a headshot for every seat in the front row, each with a personal message: "To Linda. Keep the top down." The front row is framing them.`,no:`He signs headshots down the row. "There you go. And you." They're using them as napkins.`,b:`He signs headshots. "Bobb. Bob. Bobby— no." His own name, spelled differently on each. They're using them as napkins.`}]}},
{k:'predator',n:'The Sexual Predator',g:'M',st:'sh',al:'h',tier:'prospect',pop:3,bio:"Loved the movie Predator so much he started wrestling dressed as the creature. Then one day he caught his reflection and realized he's kind of sexy. Changed his name accordingly.",
 m:{t:"{A} switches on his 'cloaking device' — a bedsheet painted to look like the arena — and disappears against the turnbuckle.",ch:[
  {t:"Decloak and hit a top-rope splash",s:'ring',d:.1,st:.5,heat:6,ok:"Nobody saw him coming. Least of all the bedsheet.",no:"The bedsheet snags on the turnbuckle."},
  {al:'h',t:"Stop mid-move to admire himself in the ring post",s:'pop',d:.05,st:.25,popA:2,ok:"He's not wrong. He does look good.",no:"{B} rolls him up while he's posing."}]},
 p:{t:"{A} walks out in the full creature mask, then slowly peels it off and shakes out his hair.",ch:[
  {key:1,t:"Explain his journey from movie superfan to heartthrob",s:'mic',d:.1,p:3,ok:`He shakes out his hair. "I was just a fan. Now I'm the leading man." The crowd boos and swoons at the same time.`,g:`"I was just a fan. A big fan. Of a big movie." He shakes out his hair. "Then I looked in the mirror and thought: I'm the leading man." The crowd boos and swoons at the same time.`,no:`He flexes. "From superfan to superstar." The crowd chants for him to put the mask back on.`,b:`He flexes. "It all started with my favorite movie, Alien." Wrong movie. The crowd chants for him to put the mask back on.`},
  {t:"Flex, blow a kiss to the hard camera, and leave",s:'pop',d:.05,p:2,ok:`He flexes and blows a kiss to the hard camera. "Ladies." And leaves. Somehow it works.`,g:`He flexes, blows one slow kiss straight into the hard camera, and says only: "You're welcome." Then walks out. Somehow it works.`,no:`He flexes. "Hey there." Blows a kiss. It's a lot.`,b:`He blows a kiss to the wrong camera. "Over — here, sorry." Then the right one. Then trips on the steps. It's a lot.`}]}},
{k:'minotaur',n:'Pat Minotaur',g:'M',st:'pw',al:'h',tier:'prospect',ring:2,bio:"Half man, half bull, all Pat. Lives in a labyrinth (a two-bedroom in Delaware with a very confusing floor plan).",
 m:{t:"{A} scrapes his boot across the mat and lowers his horns at {B}.",ch:[
  {t:"Charge! Full-speed gore",s:'ring',d:.1,st:.5,heat:8,ok:"{B} goes flying through the ropes. Olé.",no:"{B} sidesteps and Pat hits the turnbuckle horns-first."},
  {al:'h',t:"Trap {B} in the corner — the labyrinth has no exit",s:'luck',d:.05,st:.5,heat:10,ok:"There's no way out. There's never a way out.",no:"{B} finds the exit. It was the ropes."}]},
 p:{t:"{A} snorts into the microphone for a full thirty seconds.",ch:[
  {key:1,t:"Challenge any hero brave enough to enter the labyrinth",s:'mic',d:.1,p:3,ok:`He snorts into the mic. "Any hero brave enough. Enter the labyrinth." Nobody volunteers. The crowd is genuinely scared.`,g:`He snorts once into the mic. "Any hero brave enough. Enter the labyrinth." A pause. "Bring a map. Nobody ever brings a map." Nobody volunteers. The crowd is genuinely scared.`,no:`He snorts. "Enter my labyrinth, if you dare!" Someone yells "Is that the one in Delaware?"`,b:`He snorts. "Enter the labyrinth! It's at 4400 Route 9." Someone asks if it's the one in Delaware.`},
  {t:"Get the crowd waving red towels",s:'pop',d:.05,p:2,ok:`He waves a red towel. "Wave them!" A sea of red. Pat is losing his mind.`,g:`He pulls out a red towel and waves it once. "Now you." The whole building waves back, a sea of red, and he paws the mat and snorts. Pat is losing his mind.`,no:`He waves a towel. "Everybody! Red towels!" One guy brought a towel. It's beige.`,b:`He waves his towel. "Red towels! ...Mine's beige." So is the one guy's. Pat is losing his mind for the wrong reason.`}]}},
{k:'priest',n:'"The Catholic Priest" Saul Lebowitz',g:'M',st:'te',al:'f',tier:'prospect',bio:"Insists he is a Catholic priest. Has never once explained the name. The locker room stopped asking years ago.",
 m:{t:"{A} pauses to bless the ring, the referee and, somehow, {B}.",ch:[
  {t:"Hit a Hail Mary crossbody off the top",s:'ring',d:.15,st:.5,popA:2,ok:"A miracle on the top rope.",no:"It was not answered."},
  {t:"Hear {B}'s confession in the middle of a headlock",s:'mic',d:.1,st:.25,heat:6,ok:"{B} confesses everything. Including the tights.",no:"{B} has nothing to confess. Apparently."}]},
 p:{t:"{A} walks to the ring swinging incense. The smoke alarm considers its options.",ch:[
  {key:1,t:"Deliver a sermon on the sin of cheating",s:'mic',d:.1,p:3,ok:`He raises his hands. "Thou shalt not pull the tights." Even the heels in the back feel guilty.`,g:`"Brothers and sisters. Thou shalt not pull the tights." He looks out over the incense. "Thou shalt not feet on the ropes. And thou shalt not — ever — use the ref." Even the heels in the back feel guilty.`,no:`He opens the book. "Chapter nine, verse four, on the matter of the rope break—" The congregation falls asleep.`,b:`He raises his hands. "I confess I once used the ropes. And a chair. And the ref, twice—" The congregation falls asleep.`},
  {t:"Take one question about the name",s:'luck',d:.1,p:2,ok:`A fan asks about the name. He nods. "It came to me in a vision. It's in the book." Nobody understands it. Everybody accepts it.`,g:`He takes the question and nods solemnly. "The name chose me. Long before I was born. And that's in the book." Total confidence. Nobody understands it. Everybody accepts it.`,no:`A fan asks about the name. He stares. "...Next question." He stares until they sit down.`,b:`A fan asks about the name. He opens his mouth. "It's — well — hm." Closes it. Stares at the fan until they sit down.`}]}},
{k:'deppcuz',n:"Johnny Depp's Cousin",g:'M',st:'sh',al:'h',tier:'prospect',mic:3,bio:"Says he's Johnny Depp's cousin. Can't name a single other family member. Brings it up constantly.",
 m:{t:"{A} stops mid-match to remind everyone that his cousin is a very famous actor.",ch:[
  {t:"Hit his finisher, The Family Connection",s:'ring',d:.1,st:.5,heat:6,ok:"Connected.",no:"There is no connection. There never was."},
  {al:'h',t:"Warn {B} that his cousin knows people",s:'mic',d:.05,st:.25,heat:10,ok:"{B} hesitates just long enough to get pinned.",no:"{B} asks for the cousin's number."}]},
 p:{t:"{A} holds up a blurry photo of the back of someone's head.",ch:[
  {key:1,t:"Insist that's definitely his cousin",s:'mic',d:.1,p:3,ok:`He holds up a blurry photo. "That's my cousin." The crowd chants "THAT'S NOT HIM!"`,g:`He holds the photo up beside his face. "Same ears. Same jaw. That's my cousin. Ask anyone in the family." The crowd chants "THAT'S NOT HIM!"`,no:`He holds up the photo. "My cousin. Look at the resemblance." It's very clearly a mailbox.`,b:`He holds up the photo. "My cousin! See?" It's very clearly a mailbox. "He's shy." He insists anyway.`},
  {t:"Name-drop every movie he can think of",s:'mic',d:.05,p:2,ok:`He counts on his fingers. "My cousin's been in everything. The pirate one. The chocolate one. The one with the scissors." A few he made up.`,g:`He names every movie, in order, with the year. "Nineteen ninety. The scissors one. Brilliant." Three are completely made up, and he says those with the most confidence.`,no:`He thinks. "The pirate one. The other pirate one. The third pirate one." He only knows the pirate ones.`,b:`He counts. "Pirates. Pirates Two. Pirates Again. Pirates." Some of them twice.`}]}},
{k:'bakula',n:'Scott Bakula',g:'M',st:'te',al:'f',tier:'prospect',bio:"Not that Scott Bakula. No relation. Gets asked about it every single day and has made his peace with it.",
 m:{t:"Someone in the crowd yells 'Oh boy!' and {A} visibly sighs.",ch:[
  {t:"Take a quantum leap off the top rope",s:'ring',d:.15,st:.5,popA:2,ok:"He lands somewhere else entirely — right on top of {B}.",no:"He leaps. He does not land well."},
  {t:"Ignore it and wrestle a technical clinic",s:'ring',d:.05,st:.25,ok:"The crowd finally starts chanting his actual name. Well, the same name. You know what we mean.",no:"They're still yelling 'Oh boy!'"}]},
 p:{t:"{A} starts every promo the same way: \"Not that one.\"",ch:[
  {key:1,t:"Explain, once and for all, that he is not the actor",s:'mic',d:.1,p:3,ok:`He sighs into the mic. "I'm Scott Bakula. Not that one. Never been to space." The crowd respects it. Mostly.`,g:`"I'm Scott Bakula. Not that Scott Bakula." He puts down the mic, picks it up again. "And I've never been to space. Or the past." The crowd respects it. Mostly.`,no:`He raises a hand. "I am not the actor." Someone in the front row holds out a pen anyway and asks "Sign it 'Captain'?"`,b:`He raises a hand. "I'm not the actor. Oh, boy." That's the actor's catchphrase. Someone asks for an autograph.`},
  {t:"Give in and sign the autograph",s:'pop',d:.05,p:2,ok:`He gives in and signs the autograph. "Scott Bakula (no relation)." The crowd adores him.`,g:`He sighs, takes the pen and signs: "Scott Bakula (no relation). Still a fan." He hands it back with a smile. The crowd adores him.`,no:`He signs it. "Scott Bakula. No relation." The fan reads it, frowns and says "Then I want my money back."`,b:`He gives in. "Fine. To my biggest fan, from — the actor." He signs as the actor. The fan asks for a refund.`}]}},
{k:'butternuts',n:'Francis Butternuts',g:'M',st:'fl',al:'f',tier:'prospect',bio:"Grew up on the family squash farm. Proud of the name. Will fight anyone who laughs at it.",
 m:{t:"Someone in the front row giggles at the name and {A} stops dead.",ch:[
  {t:"Take it out on {B} with a furious flurry",s:'ring',d:.1,st:.5,popA:2,ok:"Nobody's laughing now.",no:"Too fired up — he gets sloppy."},
  {t:"Dive onto the giggler's section (carefully)",s:'ring',d:.15,st:.5,fat:5,ok:"Respect restored.",no:"He lands in the nachos."}]},
 p:{t:"{A} holds up a framed family crest featuring a single butternut squash.",ch:[
  {key:1,t:"Give a heartfelt speech about family pride",s:'mic',d:.1,p:3,ok:`He holds up the family crest. "Butternuts. My grandfather's name. Say it with pride." The crowd chants "BUTTERNUTS!" with total respect.`,g:`"My great-grandfather planted the first squash in that field. My grandmother picked the last one." He holds up the crest. "Butternuts. Say it with pride." The crowd chants "BUTTERNUTS!" with total respect.`,no:`He holds up the crest. "My family name means everything to me." Somebody laughs. It's over.`,b:`He holds up the crest. "Butternuts. Butter... nuts. Heh." He laughs at his own name halfway through. It's over.`},
  {t:"Hand out squash to the front row",s:'pop',d:.05,p:2,ok:`He hands out squash. "Roast it at four hundred." Great roasted, apparently.`,g:`He hands each person in the front row a whole butternut squash, like a medal. "Roast it at 400. Thank me later." Great roasted, apparently.`,no:`He hands out whole squash. "Enjoy!" Nobody knows what to do with a whole squash.`,b:`He hands out squash. "Here you go, and — OW, my foot." He drops one. Nobody knows what to do with a whole squash.`}]}},
{k:'asapgreg',n:'ASAP Greg',g:'M',st:'fl',al:'h',tier:'prospect',bio:"Everything is urgent. Every email is high priority. Every match should have ended five minutes ago.",
 m:{t:"{A} checks his watch, sighs loudly and starts speed-running his offense.",ch:[
  {t:"Hit every signature move in thirty seconds",s:'ring',d:.15,st:.5,fat:6,ok:"Efficient. Terrifyingly efficient.",no:"He skipped a step. Several steps."},
  {al:'h',t:"Tell the referee to count faster",s:'luck',d:.05,st:.25,heat:10,ok:"The rattled ref counts at double speed. Three!",no:"The ref slows down out of spite."}]},
 p:{t:"{A} jogs to the ring, already mid-sentence.",ch:[
  {key:1,t:"Deliver the whole promo in eleven seconds",s:'mic',d:.1,p:3,ok:`He takes a breath. "BigmatchSundayI'mwinningbeatmeifyoucangoodnight." Eleven seconds. Nobody caught a word. Everybody loved it.`,g:`Eleven seconds: "I'mbetterI'mfasterI'mreadyandI'malreadylate." Every word clear, every point made, and a mic drop on the twelfth. Everybody loved it.`,no:`He rattles it off. "Sunday-big-match-I'm-gonna—" Too fast, even for him.`,b:`He goes for it. "Sundaybigmatchgonnawin—" He runs out of breath at nine. "...hah... hold on." Too fast, even for him.`},
  {t:"Mark the segment URGENT and leave",s:'pop',d:.05,p:2,ok:`He slaps a sticker on the turnbuckle. "URGENT. Handle it." And leaves. The crowd respects the hustle.`,g:`He slaps an URGENT sticker on the turnbuckle, points at it — "Today." — and jogs out. The crowd respects the hustle.`,no:`He slaps a sticker on the post. "This is urgent!" Nobody knows what was urgent.`,b:`He marks it urgent and jogs out. Then jogs back in. "What was urgent?" Nobody knows.`}]}},
{k:'beefsteak',n:'Beefsteak Tony',g:'M',st:'br',al:'f',tier:'prospect',pop:3,bio:"A big man with a big appetite and a bigger family. Every cousin is in the front row, and every cousin is named Tony.",
 m:{t:"The Tony section in the front row starts pounding on the barricade.",ch:[
  {t:"Feed off the Tonys and hit a running splash",s:'pop',d:.05,st:.5,popA:2,ok:"The Tonys go wild.",no:"The Tonys are disappointed. All of them."},
  {t:"Toss {B} into the Tony section",s:'ring',d:.1,st:.5,heat:8,ok:"The Tonys toss {B} right back in.",no:"The Tonys catch {A} instead."}]},
 p:{t:"{A} comes out with a steak on a fork and a napkin tucked into his singlet.",ch:[
  {key:1,t:"Introduce every Tony in the front row",s:'mic',d:.1,p:3,ok:`He points down the front row. "Tony. Tony. Tony. Tony. And Big Tony!" Every one of them gets a huge pop.`,g:`"Tony. Tony. Tony. Tony. Big Tony. Little Tony. Tony's Tony." Each one stands for a pop. The last one is a baby. Huge pop.`,no:`He points down the row. "Tony. Tony. Tony. Tony. Tony. Tony. Tony. Uh — Tony?" He loses count around Tony number nine.`,b:`He points down the row. "Tony, Tony, Frank—" Frank is Tony. "Tony! Sorry, Tony." He loses count.`},
  {t:"Challenge the whole locker room to an eating contest",s:'mic',d:.05,p:2,ok:`He points a fork at the curtain. "Anybody in the back. Eating contest. Twelve pounds of ribs." The crowd desperately wants to see it.`,g:`"Me. Anybody in the back. Twelve pounds of ribs." He points the fork at the curtain. "Winner gets the belt. Loser gets the bill." The crowd desperately wants to see it.`,no:`He raises a fork. "Twelve pounds of ribs! Who's in?" Nobody takes him up on it. Smart.`,b:`He raises the fork. "Anybody in the back — mmf — eating contest — mmf—" He eats the steak while he's still talking. Nobody takes him up on it.`}]}},
{k:'wingspan',n:'"Wingspan" Hawk Barnaby',g:'M',st:'fl',al:'f',tier:'bluechip',ring:2,bio:"Arm span of a small aircraft. Will tell you the exact measurement in centimeters, then inches, then hawks.",
 m:{t:"{A} spreads his arms wide on the top rope. His shadow covers half the ring.",ch:[
  {t:"Soar off the top with a wingspan crossbody",s:'ring',d:.15,st:.75,popA:2,fat:5,ok:"He blots out the arena lights. Majestic.",no:"Clips the ring post with a wing."},
  {t:"Clothesline {B} from impossibly far away",s:'ring',d:.1,st:.5,ok:"He didn't even move. The arms did.",no:"Too far. Way too far."}]},
 p:{t:"{A} stretches his arms across the entire ring for his entrance pose.",ch:[
  {key:1,t:"Announce his exact wingspan to a hushed crowd",s:'mic',d:.1,p:3,ok:`He spreads his arms. "Eighty-three inches." The crowd gasps. That's huge.`,g:`"Two hundred and eleven centimeters. Eighty-three inches." A long pause. "Roughly one-point-four hawks." The crowd gasps. That's huge.`,no:`He spreads his arms. "Eighty-three inches." Somebody yells "My uncle's is bigger!" It sticks.`,b:`He spreads his arms. "Eighty-three inches. That's — eleven meters." It isn't. Someone yells that their uncle's is bigger.`},
  {t:"High-five the entire front row in one sweep",s:'pop',d:.05,p:2,ok:`He runs the barricade, arms out. "Up top!" Twenty high fives in one sweep.`,g:`He sweeps the barricade, arms out, without even looking. "Up top, up top, up top—" Twenty high fives, not one missed.`,no:`He swings his arms out. "Up top, everyb—" He knocks over a camera.`,b:`He goes for the sweep. "Up — sorry! Sorry!" He smacks a camera operator. Then a second one.`}]}},
{k:'bubbler',n:'Dave "The Bubbbler" Sandoval',g:'M',st:'pw',al:'f',tier:'prospect',bio:"Wisconsin's own. Refuses to call it a water fountain. Will fight you about it. (Yes, three b's. Don't ask.)",
 m:{t:"{A} takes a long sip from the bubbler he insisted they install next to the ring post.",ch:[
  {t:"Spray a mist of bubbler water and hit the powerslam",s:'ring',d:.1,st:.5,ok:"Hydrated and dominant.",no:"Water on the mat. He slips."},
  {t:"Make {B} admit it's called a bubbler",s:'mic',d:.1,st:.25,heat:8,ok:"\"FINE! It's a bubbler!\" {B} taps out on principle.",no:"{B} says 'water fountain.' This is war."}]},
 p:{t:"{A} wheels a drinking fountain to the ring on a dolly.",ch:[
  {key:1,t:"Explain, at length, why it's called a bubbler",s:'mic',d:.1,p:3,ok:`He pats the machine. "It's a bubbler. You bubble. You don't fount." The whole crowd chants "BUB-BLER!"`,g:`"A water fountain is a decoration in a mall. This —" he pats the machine "— is a bubbler. You bubble. You don't fount." The whole crowd chants "BUB-BLER!"`,no:`He pats the machine. "This is a bubbler." Someone yells that it's a water fountain. It gets heated.`,b:`He pats the machine. "This water fountain is called a — no. Bubbler." It gets heated.`},
  {t:"Offer the front row a drink",s:'pop',d:.05,p:2,ok:`He presses the button. "Drink up. Wisconsin's finest." Refreshing.`,g:`He presses the button and holds the arc steady for each fan in the front row. "Wisconsin's finest." Refreshing.`,no:`He holds the arc out. "Have a sip!" It's lukewarm.`,b:`He leans over the bubbler. "Have a — PFFT!" It sprays him in the face. It's lukewarm.`}]}},
{k:'finewine',n:'"Fine Wine" Whitney Cheese',g:'F',st:'te',al:'f',tier:'bluechip',mic:4,bio:"Only gets better with age. Pairs well with any opponent. Brings a charcuterie board to every match.",
 m:{t:"{A} swirls an imaginary glass and studies {B} like a vintage.",ch:[
  {t:"Uncork a perfectly aged submission",s:'ring',d:.1,st:.5,popA:2,ok:"Complex. Full-bodied. {B} taps.",no:"Corked."},
  {t:"Pair {B}'s offense with the perfect counter",s:'ring',d:.05,st:.25,ok:"A flawless pairing.",no:"Notes of overconfidence."}]},
 p:{t:"{A} arrives with a cheese board and her own sommelier.",ch:[
  {key:1,t:"Describe her next opponent like a disappointing wine",s:'mic',d:.1,p:3,ok:`She describes her next opponent like a disappointing wine. "Thin. Bitter." The crowd howls.`,g:`She swirls the glass. "Your opponent: thin. A little sour. No finish." A sip. "Gone too soon." The crowd howls.`,no:`She swirls the glass. "Notes of fear. A hint of oak. A bouquet of — cardboard, wet dog, regret, a sort of mid-palate—" Too many tasting notes.`,b:`She swirls the glass. "Your opponent is like a — a red. No, a white. A sparkling, sort of, with cheese—" She loses track of the metaphor. Too many tasting notes.`},
  {t:"Share the cheese board with the front row",s:'pop',d:.05,p:2,ok:`She walks the barricade with the board. "Brie? Brie for you?" The brie goes fast.`,g:`She walks the barricade with the board, a slice for every seat. "The brie pairs with you. The cheddar pairs with you." The brie goes fast.`,no:`She holds out the board. "The blue is divine." Nobody wants the blue cheese.`,b:`She holds out the board. "Cheese for every — oh no." She drops it. Nobody wants the floor cheese.`}]}},
{k:'apollo',n:'"Apollo 11" Michael Collins',g:'M',st:'te',al:'f',tier:'prospect',bio:"Named for the astronaut who flew Apollo 11 and stayed with the ship while the other two walked on the Moon. Same energy: always reliable, never in the photo.",
 m:{t:"{A} circles patiently on the outside while everyone else gets the spotlight.",ch:[
  {t:"Wait for the perfect moment, then launch",s:'ring',d:.1,st:.5,popA:2,ok:"Liftoff.",no:"Mission scrubbed."},
  {t:"Stay in orbit and let {B} wear themselves out",s:'luck',d:.05,st:.25,ok:"Patience pays off. {B} is exhausted.",no:"{B} is also patient. Nothing happens for six minutes."}]},
 p:{t:"{A} walks out in a vintage flight suit to a ten-second countdown.",ch:[
  {key:1,t:"Give a stirring speech about the unsung heroes",s:'mic',d:.1,p:3,ok:`He looks up at the lights. "This is for everybody who does the work and never gets the credit." There isn't a dry eye in the house.`,g:`"Everybody knows two names from that mission." He looks up at the lights. "Somebody had to stay behind and fly the ship. That's me. That's every one of you who never gets the credit." There isn't a dry eye in the house.`,no:`He salutes the rafters. "To the unsung heroes!" The crowd starts chanting for the other two guys.`,b:`He begins. "This is for the unsung — Neil and Buzz. And me." He names the other two first. The crowd chants for them.`},
  {t:"Salute the crowd and let them do the rest",s:'pop',d:.05,p:2,ok:`He salutes the crowd and lets them do the rest. "COL-LINS! COL-LINS!" The ship holds steady.`,g:`He snaps a salute and holds it. Nothing else. The crowd does the rest: "COL-LINS! COL-LINS!" The ship holds steady.`,no:`He salutes. "Houston?" Silence. Houston, we have a quiet crowd.`,b:`He salutes with the wrong hand. "Hang on." Fixes it. Houston, we have a quiet crowd.`}]}},
{k:'tiger',n:'Tony "The Gay" Tiger',g:'M',st:'sh',al:'f',tier:'bluechip',pop:6,mic:4,bio:"Out, proud and GRRREAT. Has the best entrance in the company and an unbeatable breakfast routine.",
 m:{t:"{A} strikes a pose on the turnbuckle and the whole crowd roars along with him.",ch:[
  {t:"Pounce off the top rope",s:'ring',d:.1,st:.5,popA:2,ok:"GRRREAT!",no:"A little less than great."},
  {t:"Strut, pose, then hit the finisher",s:'pop',d:.05,st:.5,popA:2,ok:"Confidence is a finishing move.",no:"{B} interrupts the strut. Rude."}]},
 p:{t:"{A} arrives to a rainbow-lit entrance, carrying a bowl of cereal.",ch:[
  {key:1,t:"Tell the crowd to start every day like a champion",s:'mic',d:.1,p:3,ok:`He lifts the cereal bowl. "Start every day like a champion!" The whole building roars: GRRREAT.`,g:`He lifts the cereal bowl. "Start every day like a champion. Proud. Loud. With milk." The whole building roars: GRRREAT.`,no:`He lifts the bowl. "Start every day like a champion!" It's a night show. The breakfast message doesn't land.`,b:`He lifts the bowl. "Every day like a champ— oops." He spills the cereal. The breakfast message doesn't land.`},
  {t:"Toss mini cereal boxes into the crowd",s:'pop',d:.05,p:2,ok:`He hurls a mini box into the crowd. "Part of a balanced breakfast!" The front row fights over the frosted ones.`,g:`He sends a mini box into every section, one after another, never missing. "That one's yours, kid." The last one lands right in a kid's hands. The front row fights over the frosted ones.`,no:`He wings a box into the stands. "Heads up!" Someone gets bonked.`,b:`He tosses the boxes. "Catch! Catch! ...Catch?" Every one falls short into the timekeeper's area. Someone gets bonked.`}]}},
{k:'turbo',n:'Todd N Turbo',g:'M',st:'fl',al:'f',tier:'prospect',pop:4,bio:"Comes out to \"Thunderstruck\" by AC/DC every single week, no matter what it costs. It costs a lot.",
 m:{t:"The arena DJ accidentally plays {A}'s music mid-match, and he's instantly re-energized.",ch:[
  {t:"Go full turbo with a flurry of strikes",s:'ring',d:.1,st:.5,popA:2,ok:"Thunder. Struck.",no:"Turbo lag."},
  {t:"Air guitar on the top rope",s:'pop',d:.1,st:.25,popA:2,ok:"The whole crowd plays along.",no:"{B} unplugs him."}]},
 p:{t:"That opening guitar riff hits, and {A} sprints to the ring.",ch:[
  {key:1,t:"Get the whole building chanting along",s:'pop',d:.1,p:3,ok:`He raises both arms. "Let me hear you!" Twenty thousand people chanting. Goosebumps.`,g:`He cuts the music and leads it himself. "Again! AGAIN!" One hand up, one hand down, until twenty thousand people are chanting in time. Goosebumps.`,no:`He raises his arms. "Let me hear—" The music cuts out early. Licensing.`,b:`He starts the chant. The music cuts out. He keeps going, alone: "Hey! Hey! ...Hey." Licensing.`},
  {t:"Explain what the 'N' stands for",s:'mic',d:.05,p:2,ok:`He leans into the mic. "Everybody asks what the N stands for. It stands for N." Iconic.`,g:`"Everybody asks what the N stands for." He leans into the mic. "N." He puts the mic down. Iconic.`,no:`He holds up a finger. "You want to know what the N stands for?" Nobody asked.`,b:`He explains. "The N stands for — Nitro. No, Nice. Or — Neal?" Three different answers. Nobody asked.`}]}},
{k:'hughandshake',n:"Dustin \"I Don't Know if I'm Supposed to Hug or Shake Hands with This Girl I Met Once Before\" Howard",g:'M',st:'te',al:'f',tier:'prospect',bio:"Socially paralyzed. Longest nickname in wrestling. The ring announcer needs a water break halfway through it.",
 m:{t:"{B} offers a pre-match handshake just as {A} goes in for a hug.",ch:[
  {t:"Commit to the hug",s:'luck',d:.1,st:.5,popA:2,ok:"It's awkward, it's sweet — and then it's a German suplex.",no:"It becomes a half-hug, half-handshake. Everyone dies a little inside."},
  {t:"Panic and go for a roll-up",s:'luck',d:.05,st:.25,ok:"It's so awkward {B} never sees it coming. Three!",no:"{B} kicks out. More awkwardness."}]},
 p:{t:"The ring announcer starts {A}'s full nickname. Two minutes later, he's still going.",ch:[
  {key:1,t:"Thank the announcer, wave, then also try to shake his hand",s:'pop',d:.1,p:3,ok:`He thanks the announcer. "Thanks, pal." Waves. Then goes for the handshake too. The crowd feels this one in their bones.`,g:`He thanks the announcer — "Appreciate you." — waves, then reaches for the handshake, which the announcer meets perfectly. They hold it. The crowd feels this one in their bones.`,no:`He waves at the announcer. "Thank — oh, are we —" Nobody knows where to look.`,b:`He waves. "Thanks!" Then goes for the handshake. Then the hug. Then the wave again. Nobody knows where to look.`},
  {t:"Tell the story of the girl he met once before",s:'mic',d:.05,p:2,ok:`He clears his throat. "I met a girl once. Lane seven. If you're out there, I still think about lane seven." The whole building is rooting for him.`,g:`"I met a girl once. At a bowling alley. I never got her name." He looks at the crowd. "If you're here tonight — lane seven. I still think about lane seven." The whole building is rooting for him.`,no:`He starts. "I met a girl once—" She's in the front row. He freezes.`,b:`He starts. "There was this girl at the bowling—" She's in the front row. She waves. He drops the mic.`}]}},
{k:'binoculars',n:'"Looks Good from Here" Brian Binoculars',g:'M',st:'sh',al:'h',tier:'prospect',bio:"Watches every match through binoculars. From inside the ring. Including his own.",
 m:{t:"{A} backs into the far corner and studies {B} through his binoculars.",ch:[
  {t:"Spot the weakness and strike",s:'ring',d:.1,st:.5,heat:6,ok:"Looked good from there. Looks even better up close.",no:"He was looking through the wrong end."},
  {al:'h',t:"Clock {B} with the binoculars",loseNo:'dq',s:'luck',d:.05,st:.5,heat:12,ok:"Pinpoint accuracy.",no:"The ref saw it. Without binoculars."}]},
 p:{t:"{A} surveys the crowd through binoculars for a very long time.",ch:[
  {key:1,t:"Rate the crowd from a distance",s:'mic',d:.1,p:3,ok:`He rates the crowd from a distance. "Looks good from here." The crowd boos and cheers at once.`,g:`He raises the binoculars and scans section by section. "Looks good from here." A pause. "That section, less so." The crowd boos and cheers at once.`,no:`He lowers the binoculars. "Four out of ten." The crowd is furious.`,b:`He peers through the binoculars. "Huh. Tiny. You're all tiny. Four." They're backwards. They are furious.`},
  {t:"Spot someone in the upper deck and wave",s:'pop',d:.05,p:2,ok:`He spots someone in the upper deck. "I see you up there!" Waves. The upper deck goes nuts.`,g:`He spots someone in the very last row, adjusts the focus and waves. "Row ZZ! Seat twelve! You're beautiful!" They wave back. The upper deck goes nuts.`,no:`He waves up at the upper deck. "Hello up there!" Nobody's up there.`,b:`He waves at the upper deck. "Hi! Hiiii!" Nobody's up there. He keeps waving anyway.`}]}},
{k:'kraken',n:'Mick "The Kraken" McKraken',g:'M',st:'pw',al:'h',tier:'bluechip',ring:2,bio:"Rises from the deep every Wednesday night. Says he has eight limbs (the other four are 'emotional'). Smells faintly of low tide.",
 m:{t:"Someone yells 'RELEASE THE KRAKEN!' and {A} rises from underneath the ring.",ch:[
  {t:"Wrap {B} up in the tentacle hold",s:'ring',d:.1,st:.5,heat:8,ok:"Every limb accounted for. {B} taps.",no:"He runs out of tentacles."},
  {al:'h',t:"Drag {B} under the ring — back to the deep",s:'luck',d:.1,st:.5,heat:12,ok:"{B} reappears a minute later, damp and defeated.",no:"Officials pull {B} back out by the ankles."}]},
 p:{t:"Fog floods the ramp. {A} emerges from it, dripping.",ch:[
  {key:1,t:"Threaten to drag the whole roster to the depths",s:'mic',d:.1,p:3,ok:`He drips onto the mat. "I'll drag every one of you down to the depths." The crowd is genuinely nervous.`,g:`He drips onto the mat. "Every one of you in the back. I'll take you down. Down where it's cold. Down where nobody hears." The crowd is genuinely nervous.`,no:`He raises his arms. "To the depths, all of—" The fog machine drowns him out.`,b:`He raises his arms. "To the — *cough* — depths — *cough*" The fog machine drowns him out.`},
  {t:"Squirt the front row with 'ink' (it's water)",s:'pop',d:.05,p:2,ok:`He fills his cheeks, leans over the barricade and sprays. "Splash zone!" The splash zone loves it.`,g:`He fills his cheeks, leans over the barricade and sprays the splash zone in one long, perfect arc. "Behold the ink!" They scream with joy.`,no:`He sprays the front row. "Ink!" It was actually ink.`,b:`He sprays the front row. "Behold the — *glug*" He swallows the water. Tries again. It was actually ink.`}]}},
{k:'samurai',n:'"No Gimmicks Needed" Steve the Samurai',g:'M',st:'te',al:'h',tier:'gen',mic:-4,bio:"Full armor. Foam katana. Battle flag. A gong. Insists he has no gimmick and is just a regular guy named Steve.",
 m:{t:"{A} draws a foam katana and bows deeply to {B}.",ch:[
  {t:"Hit a precise, honorable suplex",s:'ring',d:.1,st:.75,ok:"Clean. Disciplined. Still in full armor.",no:"The armor is very heavy."},
  {al:'h',t:"Use the foam katana while the ref looks away",s:'luck',d:.05,st:.25,heat:10,ok:"It doesn't hurt, but {B} is too confused to move.",no:"The ref confiscates it. Steve is heartbroken."}]},
 p:{t:"A gong sounds as {A} walks out in full samurai armor.",ch:[
  {key:1,t:"Insist he has no gimmick",s:'mic',d:.1,p:3,ok:`He insists he has no gimmick. "I'm just Steve." The gong sounds again. The crowd loses it.`,g:`The gong sounds. "I'm just Steve." The gong sounds again. "No gimmick." Gong. He doesn't look at it once. The crowd loses it.`,no:`He shrugs inside the armor. "I'm just Steve." Someone points at the armor. "What armor?" He refuses to acknowledge it.`,b:`He insists. "No gimmick. Just Steve." The armor falls off one arm. "Just Steve." He refuses to acknowledge it.`},
  {t:"Meditate in the center of the ring",s:'pop',d:.05,p:2,ok:`He kneels in the center. "Breathe." Twenty thousand people go silent. Powerful.`,g:`He kneels, closes his eyes. "Be still." One by one, sections go quiet, until the whole building is silent. Powerful.`,no:`He kneels. "Be still." Someone starts a "BORING" chant.`,b:`He kneels. "Be still... be still... zzz." He falls asleep. Someone starts a "BORING" chant.`}]}},
{k:'cuba3',n:'Cuba Gooding the Third',g:'M',st:'sh',al:'f',tier:'prospect',pop:3,bio:"Insists the name is a proud family tradition. Will not say where 'the Second' is. Extremely confident about all of it.",
 m:{t:"{A} points at {B} and yells \"SHOW ME THE MOVES!\"",ch:[
  {t:"Hit a showstopping spinning heel kick",s:'ring',d:.15,st:.5,popA:2,ok:"An award-worthy performance.",no:"Straight to video."},
  {t:"Celebrate early with a victory dance",s:'pop',d:.05,st:.25,popA:2,ok:"The crowd dances with him. Then he wins.",no:"{B} rolls him up mid-dance."}]},
 p:{t:"{A} comes out in a tuxedo, clutching a trophy he will not explain.",ch:[
  {key:1,t:"Give an acceptance speech for an award nobody gave him",s:'mic',d:.1,p:3,ok:`He clutches an imaginary trophy. "I want to thank my agent, my mom, and the Second." The crowd is moved.`,g:`He clutches the trophy. "I want to thank my agent. My mom. And the Second, who made all of this possible." He wipes an eye. The crowd is moved.`,no:`He clutches the trophy. "I'd like to thank—" The music plays him off.`,b:`He clutches the trophy. "Thank you to the Baldwins!" Wrong family. The music plays him off.`},
  {t:"Ask the crowd to show him some love",s:'pop',d:.05,p:2,ok:`He opens his arms. "Show me some love!" They show him a LOT of love.`,g:`He opens his arms. "Show me some love." And waits. And they show him a LOT of love — the whole building, on its feet.`,no:`He opens his arms. "Show me some love!" Lukewarm. He's hurt.`,b:`He points the mic. "Show me some love!" Wrong side of the arena. Lukewarm. He's hurt.`}]}},
{k:'cooldad',n:'"Cool Dad" Don Crenshaw',g:'M',st:'br',al:'f',tier:'prospect',pop:3,bio:"Grills in the parking lot before every show. Calls everyone 'champ'. Wears his sunglasses on the back of his head.",
 m:{t:"{A} stops to adjust his sunglasses and tell {B} he's proud of the effort.",ch:[
  {t:"Dad strength: one perfect bodyslam",s:'ring',d:.05,st:.5,popA:2,ok:"He didn't even spill his iced tea.",no:"He pulled something. He'll be fine. He says."},
  {t:"Give {B} a pep talk mid-match",loseNo:'pin',s:'mic',d:.1,st:.25,ok:"{B} feels great about themselves — and gets pinned.",no:"{B} feels great about themselves and wins."}]},
 p:{t:"{A} walks out in cargo shorts, holding grill tongs.",ch:[
  {key:1,t:"Tell the crowd a dad joke",s:'mic',d:.1,p:3,ok:`He leans in. "Why can't you trust stairs? They're always up to something." The groan is deafening. It's perfect.`,g:`"Why can't you trust stairs?" Long pause. "They're always up to something." He waits. The groan is deafening. It's perfect.`,no:`He starts. "So a guy walks into a hardware store, and he's looking for — what was he looking for — so he goes to aisle three—" It ran long. He lost the punchline.`,b:`He leans in. "Why are stairs always up to something? Because you can't trust them." Backwards. It ran long. He lost it.`},
  {t:"Toss hot dogs off the grill to the crowd",s:'pop',d:.05,p:2,ok:`He flips the dogs with the tongs. "Who's hungry?" Perfect grill marks. The fans love him.`,g:`He flips each dog with the tongs, perfect grill marks, and sends them into the crowd in buns. The last one he keeps. "Chef's privilege." The fans love him.`,no:`He tosses a hot dog. "Catch!" He forgot the buns.`,b:`He tosses the dogs. "Catch! Oh — buns. Plates. These are raw." He forgot everything.`}]}},
{k:'volkoff',n:'Nickleback Volkoff',g:'M',st:'pw',al:'h',tier:'prospect',mic:3,bio:"Before every match he demands the crowd stand in silence while he sings an entire Nickelback song. They have never once done it.",
 m:{t:"{A} grabs the ring announcer's mic and starts singing. {B} is begging him to stop.",ch:[
  {al:'h',t:"Keep singing until {B} snaps",s:'mic',d:.1,st:.5,heat:12,ok:"{B} charges in a blind rage — straight into a powerslam.",no:"{B} puts in earplugs."},
  {t:"Stop singing and just wrestle",s:'ring',d:.05,st:.25,ok:"The crowd cheers. Mostly because he stopped singing.",no:"He hums the rest of the match."}]},
 p:{t:"{A} demands the crowd rise 'for the anthem.'",ch:[
  {key:1,t:"Sing the whole song",s:'mic',d:.1,p:3,ok:`He holds up a hand. "Everybody rise for my song." Then sings the whole thing. The boos are thunderous. Mission accomplished.`,g:`He closes his eyes. "Please rise." Then sings the whole song, every verse, with total sincerity. The boos are thunderous. Mission accomplished.`,no:`He holds up a hand. "Rise for my song!" A few people sing along. That's somehow worse.`,b:`He sings. "Verse two goes — hmm." He forgets the second verse. A few people sing it for him. That's somehow worse.`},
  {t:"Insult the town's taste in music",s:'mic',d:.05,p:2,ok:`He sneers. "Your music is noise. Your radio is noise. Your city is noise." The crowd has never hated anyone more.`,g:`"I came here expecting music. I heard what you play in your cars." A slow shake of the head. "I've never been more disappointed in a city." The crowd has never hated anyone more.`,no:`He sneers. "Your music is terrible." The crowd shrugs. They kind of agree with him.`,b:`He sneers. "I hate your music. Especially that local band, the Rivertones." They love the Rivertones. They kind of agree, anyway.`}]}},
{k:'boomer',n:'Boomer Scarborough',g:'M',st:'br',al:'h',tier:'prospect',bio:"Believes any problem can be solved with a firm handshake and a printed résumé. Owns a landline. Is 26.",
 m:{t:"{A} tries to hand {B} a printed challenge mid-match.",ch:[
  {t:"Apply The Firm Handshake, a grip of death",s:'ring',d:.1,st:.5,ok:"Firm. Eye contact. {B} taps.",no:"Limp. Disappointing."},
  {al:'h',t:"Lecture {B} about how nobody wants to work anymore",s:'mic',d:.1,st:.25,heat:8,ok:"{B} is so annoyed they make a mistake.",no:"{B} says \"OK, Boomer.\" Devastating."}]},
 p:{t:"{A} reads his promo off a printed sheet in a plastic sleeve.",ch:[
  {key:1,t:"Complain about the price of everything",s:'mic',d:.1,p:3,ok:`He reads from a sheet. "Fourteen dollars for a sandwich. In my day, a sandwich was a nickel." The crowd groans in agreement.`,g:`He reads from the sheet. "A sandwich: fourteen dollars. A ticket: ninety dollars. Respect: free." He looks up. "And you still can't afford it." The crowd groans in agreement.`,no:`He reads. "Item one: — wait, this is my tax form." He reads the wrong page.`,b:`He reads the wrong page. "One coffee, two twenty-five. One muffin—" It's a receipt. He reads it anyway.`},
  {t:"Hand out business cards",s:'pop',d:.05,p:2,ok:`He hands out cards. "Call me. Monday. Nine sharp." Surprisingly classy cards.`,g:`He walks the barricade, handing one card to each fan with a firm handshake and eye contact. "Call me. I'll be in on Monday." Surprisingly classy cards.`,no:`He holds out cards. "Networking opportunity!" Nobody takes one.`,b:`He hands out cards. "Senior Manager, Blockbuster Video." His old job. Nobody takes one.`}]}},
{k:'keides',n:'Anthony Keides',g:'M',st:'fl',al:'f',tier:'prospect',ring:2,bio:"Wrestles shirtless, bouncing, upside down whenever possible. Spells his name differently and wants you to know it.",
 m:{t:"{A} bounces around the ring like he's at a festival, refusing to stand still.",ch:[
  {t:"Handspring into a cutter",s:'ring',d:.15,st:.5,popA:2,ok:"Pure funk.",no:"Over-bounced."},
  {t:"Hang upside down from the turnbuckle and taunt {B}",s:'pop',d:.05,st:.25,ok:"The crowd goes wild.",no:"All the blood rushes to his head."}]},
 p:{t:"{A} bounces to the ring in a beanie and absolutely nothing else above the waist.",ch:[
  {key:1,t:"Spell his last name for the crowd",s:'mic',d:.1,p:3,ok:`He holds up a finger for each letter. "K. E. I. D. E. S." The crowd spells it back.`,g:`"K. E. I. D. E. S." He holds up a finger for each letter. The crowd spells it back louder, every letter right.`,no:`He spells it. "K. I. E —" He spells it wrong. His own name.`,b:`He spells it. "K. I. D. E. S." The crowd spells it right. "No, it's — oh." His own name.`},
  {t:"Do a headstand on the turnbuckle",s:'pop',d:.05,p:2,ok:`He kicks up onto the turnbuckle. "Whoo!" Upside down and loving it.`,g:`He kicks up into a headstand on the turnbuckle and holds it. "Look at me now!" Perfectly still, grinning upside down at the hard camera.`,no:`He kicks up. "Check this ou—" He tips over.`,b:`He kicks up. "Watch — whoa — WHOA—" He tips onto the apron, then tries again and tips the other way.`}]}},
{k:'mahogony',n:'"Hardwood" Rich Mahogony',g:'M',st:'sh',al:'h',tier:'bluechip',mic:5,bio:"Very important. Owns many leather-bound books. Everything he touches smells of rich hardwood.",
 m:{t:"{A} pauses mid-match to polish the turnbuckle with a cloth.",ch:[
  {t:"Hit the Grain of the Wood elbow drop",s:'ring',d:.1,st:.5,heat:6,ok:"Polished. Expensive. Effective.",no:"Splinters."},
  {al:'h',t:"Hit {B} with a leather-bound book",loseNo:'dq',s:'luck',d:.05,st:.5,heat:12,ok:"First edition. Very heavy.",no:"The ref saw the book. Classy cheating, though."}]},
 p:{t:"{A} enters to smooth jazz, wearing a velvet smoking jacket.",ch:[
  {key:1,t:"Read a passage from one of his leather-bound books",s:'mic',d:.1,p:3,ok:`He opens a leather-bound book. "'A man is only as fine as his finest furniture.'" The crowd is furious and somehow impressed.`,g:`He opens a leather-bound book and reads, slowly, in a voice like warm oak. "'A man is only as fine as his finest furniture.'" He closes it. The crowd is furious and somehow impressed.`,no:`He opens the book. "Chapter one. Chapter two. Chapter—" Too much reading.`,b:`He opens the book. "'Insert tab A into slot B.'" It's the manual for a lamp. Too much reading.`},
  {t:"Tell the crowd they could never afford his furniture",s:'mic',d:.05,p:2,ok:`He sniffs the turnbuckle. "Pine. You could never afford my furniture." The boos echo off his solid hardwood.`,g:`He runs a finger along the turnbuckle and sniffs it. "Pine. Of course. You could never afford my furniture. You can't even afford my smell." The boos echo off his solid hardwood.`,no:`He sneers. "You could never afford my furniture." Someone yells "IKEA!" It sticks.`,b:`He leans back on a folding chair. "You could never afford my — furniture." Someone yells "IKEA!"`}]}},
{k:'scoot',n:'Scoot Tatum',g:'M',st:'fl',al:'f',tier:'prospect',bio:"Arrives everywhere on a kick scooter. Everywhere. Including the top rope.",
 m:{t:"{A} rolls into the ring on his scooter mid-match.",ch:[
  {t:"Scoot off the apron into a dive",s:'ring',d:.15,st:.5,popA:2,fat:5,ok:"Elite scoot.",no:"He forgot to brake."},
  {t:"Land a kickflip while {B} watches",s:'pop',d:.1,st:.25,popA:2,ok:"{B} is mesmerized. Roll-up. Three!",no:"The scooter shoots into the crowd."}]},
 p:{t:"{A} scoots up the ramp, kicks off and glides all the way to the ring.",ch:[
  {key:1,t:"Challenge the locker room to a scooter race",s:'mic',d:.1,p:3,ok:`He flips up the scooter. "Ramp to ring. Anybody. Let's race." The crowd wants that race so badly.`,g:`He flips the scooter up into his hand. "Anybody. Ramp to ring. No pushing." He points at the back. "I'll even give you a head start." The crowd wants that race so badly.`,no:`He holds up the scooter. "Scooter race! Who's in?" Nobody else owns a scooter.`,b:`He kicks off. "Who wants a — whoa—" He falls off his scooter while challenging. Nobody else owns a scooter.`},
  {t:"Give his scooter to a kid in the crowd",s:'pop',d:.05,p:2,ok:`He hands his scooter to a kid. "She's yours now." The kid is losing their mind. So is everyone else.`,g:`He kneels at the barricade and hands his scooter to a kid. "Take care of her. Kick with your left." The kid is losing their mind. So is everyone else.`,no:`He hands the scooter to a kid. "Here you go." A beat. "Actually, can I have that back?"`,b:`He hands his scooter to a kid. "All yours!" Then realizes he has no way out of the arena. "Could I borrow it back?"`}]}}];
